__sources["src/scripts/crawl"] = [=[
--[[
    Crawl - game structure dumper / live traffic watcher
    ====================================================
    A diagnostic tool, not a cheat. It answers "what does this game actually
    look like, and what happens at the moment I'm supposed to act?" so a
    module can be written against real structure instead of guesses.

    Three things it produces:

      1. Snapshot   - the instance tree (classes, names, values, attributes,
                      GUI text), every remote, LocalPlayer attributes, and any
                      Lua table in memory that looks game-related.
      2. Watch      - records remote traffic, attribute changes and GUI text
                      changes for N seconds, so a round can be captured as it
                      happens.
      3. Report     - both of the above written to a file (and clipboard),
                      ready to be handed over.

    Everything is bounded (node caps, string caps, depth caps) and every
    property read is pcall'd, because plenty of instances error on access.
]]

local M = {}

local MAX_STRING = 300
local MAX_ATTRS  = 24

function M.Setup(ctx)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local settings = {
        maxNodes = 8000,
        maxDepth = 8,
        watchFor = 30,
    }

    local report = {}
    local watching = false
    local watchLog = {}

    local function out(fmt, ...)
        local ok, text = pcall(string.format, fmt, ...)
        report[#report + 1] = ok and text or tostring(fmt)
    end

    local function safe(fn, fallback)
        local ok, value = pcall(fn)
        if ok then return value end
        return fallback
    end

    local function trim(value)
        local text = tostring(value)
        if #text > MAX_STRING then
            return text:sub(1, MAX_STRING) .. ("...<%d bytes>"):format(#text)
        end
        return text
    end

    ---------------------------------------------------------------- snapshot
    local INTERESTING_CLASS = {
        RemoteEvent = true, RemoteFunction = true, BindableEvent = true,
        BindableFunction = true, UnreliableRemoteEvent = true,
        StringValue = true, IntValue = true, NumberValue = true, BoolValue = true,
        ObjectValue = true, TextLabel = true, TextButton = true, TextBox = true,
    }

    local function describe(instance)
        local class = safe(function() return instance.ClassName end, "?")
        local name  = safe(function() return instance.Name end, "?")
        local extra = {}

        if class:find("Value$") then
            extra[#extra + 1] = "Value=" .. trim(safe(function() return instance.Value end, "?"))
        end
        if class == "TextLabel" or class == "TextButton" or class == "TextBox" then
            local text = safe(function() return instance.Text end, "")
            if text ~= "" then extra[#extra + 1] = "Text=" .. trim(text) end
            local visible = safe(function() return instance.Visible end, nil)
            if visible ~= nil then extra[#extra + 1] = "Visible=" .. tostring(visible) end
        end

        local attrs = safe(function() return instance:GetAttributes() end, nil)
        if type(attrs) == "table" then
            local parts, n = {}, 0
            for key, value in pairs(attrs) do
                n = n + 1
                if n > MAX_ATTRS then parts[#parts + 1] = "..." break end
                parts[#parts + 1] = tostring(key) .. "=" .. trim(value)
            end
            if #parts > 0 then
                table.sort(parts)
                extra[#extra + 1] = "@{" .. table.concat(parts, ", ") .. "}"
            end
        end

        return ("%s %q%s"):format(class, name,
            #extra > 0 and ("  " .. table.concat(extra, "  ")) or "")
    end

    local remotes = {}

    local function walk(instance, depth, budget)
        if budget.count >= settings.maxNodes then return end
        budget.count = budget.count + 1

        local class = safe(function() return instance.ClassName end, "?")
        if class:find("Remote") or class:find("Bindable") then
            remotes[#remotes + 1] = safe(function() return instance:GetFullName() end, "?")
        end

        out("%s%s", string.rep("  ", depth), describe(instance))

        if depth >= settings.maxDepth then
            out("%s  ...", string.rep("  ", depth))
            return
        end

        local children = safe(function() return instance:GetChildren() end, nil)
        if type(children) ~= "table" then return end
        for _, child in ipairs(children) do
            walk(child, depth + 1, budget)
        end
    end

    local function snapshotTree()
        local roots = {
            "ReplicatedStorage", "ReplicatedFirst", "Workspace", "Lighting",
            "StarterGui", "StarterPlayer", "Teams", "SoundService",
        }

        for _, serviceName in ipairs(roots) do
            local service = safe(function() return game:GetService(serviceName) end, nil)
            if service then
                out("")
                out("---- %s ----", serviceName)
                walk(service, 0, { count = 0 })
            end
        end

        local gui = safe(function() return LocalPlayer:FindFirstChild("PlayerGui") end, nil)
        if gui then
            out("")
            out("---- PlayerGui ----")
            walk(gui, 0, { count = 0 })
        end

        local scripts = safe(function() return LocalPlayer:FindFirstChild("PlayerScripts") end, nil)
        if scripts then
            out("")
            out("---- PlayerScripts ----")
            walk(scripts, 0, { count = 0 })
        end
    end

    local function snapshotPlayer()
        out("")
        out("---- LocalPlayer ----")
        out("Name: %s  UserId: %s", safe(function() return LocalPlayer.Name end, "?"),
            tostring(safe(function() return LocalPlayer.UserId end, "?")))

        local attrs = safe(function() return LocalPlayer:GetAttributes() end, nil)
        if type(attrs) == "table" then
            for key, value in pairs(attrs) do
                out("  attribute %s = %s", tostring(key), trim(value))
            end
        end

        local character = safe(function() return LocalPlayer.Character end, nil)
        if character then
            local charAttrs = safe(function() return character:GetAttributes() end, nil)
            if type(charAttrs) == "table" then
                for key, value in pairs(charAttrs) do
                    out("  character attribute %s = %s", tostring(key), trim(value))
                end
            end
        end
    end

    -- Anything in memory that smells like round/word state.
    local KEY_HINTS = {
        "question", "word", "letter", "turn", "answer", "choice", "prompt",
        "round", "player", "timer", "remote", "fire", "ping", "state", "game",
    }

    local function looksInteresting(key)
        local lowered = tostring(key):lower()
        for _, hint in ipairs(KEY_HINTS) do
            if lowered:find(hint, 1, true) then return true end
        end
        return false
    end

    local function snapshotMemory()
        out("")
        out("---- tables in memory that look game-related ----")
        if not getgc then
            out("(no getgc in this executor)")
            return
        end

        local shown = 0
        local objects = safe(function() return getgc(true) end, {})
        for _, object in ipairs(objects) do
            if shown >= 120 then break end
            if type(object) == "table" then
                local keys, hits = {}, 0
                local ok = pcall(function()
                    for key, value in pairs(object) do
                        if #keys < 30 then
                            keys[#keys + 1] = tostring(key) ..
                                (type(value) == "function" and "()" or
                                 type(value) == "table" and "{}" or
                                 ("=" .. trim(value)))
                        end
                        if looksInteresting(key) then hits = hits + 1 end
                    end
                end)
                if ok and hits >= 2 and #keys > 0 then
                    shown = shown + 1
                    table.sort(keys)
                    out("  table: %s", table.concat(keys, ", "))
                end
            end
        end
        if shown == 0 then out("(nothing matched)") end

        -- strings big enough to be a word list
        out("")
        out("---- long strings in memory (possible word lists) ----")
        local strings = 0
        for _, object in ipairs(objects) do
            if strings >= 20 then break end
            if type(object) == "string" and #object > 2000 then
                strings = strings + 1
                out("  %d bytes: %s", #object, trim(object:sub(1, 200)))
            end
        end
        if strings == 0 then out("(none)") end
    end

    local function snapshotRemotes()
        out("")
        out("---- remotes found (%d) ----", #remotes)
        table.sort(remotes)
        for _, path in ipairs(remotes) do out("  %s", path) end
    end

    local function snapshotModules()
        if not getloadedmodules then return end
        out("")
        out("---- loaded module scripts ----")
        local modules = safe(function() return getloadedmodules() end, {})
        local shown = 0
        for _, module in ipairs(modules) do
            if shown >= 200 then break end
            shown = shown + 1
            out("  %s", safe(function() return module:GetFullName() end, "?"))
        end
    end

    local function crawl()
        report = {}
        remotes = {}
        out("==== namdevHub crawl ====")
        out("game: %s", tostring(ctx.GameInfo.Name))
        out("PlaceId: %d   GameId: %d   JobId: %s",
            ctx.GameInfo.PlaceId, ctx.GameInfo.GameId, tostring(ctx.GameInfo.JobId))
        out("executor: %s", tostring(ctx.Hub.Executor))
        out("clock: %s", tostring(os.time()))

        snapshotPlayer()
        snapshotTree()
        snapshotRemotes()
        snapshotMemory()
        snapshotModules()
        return table.concat(report, "\n")
    end

    ------------------------------------------------------------------ watch
    -- Records what the game does while you play a round. Remote traffic is
    -- captured through __namecall when the executor allows it; the hook is
    -- always restored, and it is also restored on unload.
    local restoreHook

    local function startRemoteHook()
        if restoreHook then return true end
        if not (getrawmetatable and setreadonly and hookmetamethod) then return false end

        local ok = pcall(function()
            local original
            original = hookmetamethod(game, "__namecall", function(self, ...)
                if watching then
                    local method = getnamecallmethod and getnamecallmethod() or "?"
                    if method == "FireServer" or method == "InvokeServer" then
                        local args = {}
                        for i = 1, select("#", ...) do
                            args[i] = trim((select(i, ...)))
                        end
                        watchLog[#watchLog + 1] = ("%.2f  %s:%s(%s)"):format(
                            os.clock(), safe(function() return self:GetFullName() end, "?"),
                            method, table.concat(args, ", "))
                    end
                end
                return original(self, ...)
            end)
            restoreHook = function()
                pcall(function() hookmetamethod(game, "__namecall", original) end)
            end
        end)
        return ok
    end

    -- Fallback / addition: wrap the fire functions on any game table that has
    -- them, so we see internal calls that never touch a RemoteEvent directly.
    local wrapped = {}

    local function wrapNetworkTables()
        if not getgc then return 0 end
        local count = 0
        for _, object in ipairs(safe(function() return getgc(true) end, {})) do
            if type(object) == "table" and not wrapped[object] then
                local ok = pcall(function()
                    for _, key in ipairs({ "fire", "remoteFire", "invoke", "remoteInvoke" }) do
                        local fn = rawget(object, key)
                        if type(fn) == "function" then
                            wrapped[object] = wrapped[object] or {}
                            wrapped[object][key] = fn
                            rawset(object, key, function(...)
                                if watching then
                                    local args = {}
                                    for i = 1, select("#", ...) do
                                        args[i] = trim((select(i, ...)))
                                    end
                                    watchLog[#watchLog + 1] = ("%.2f  net.%s(%s)"):format(
                                        os.clock(), key, table.concat(args, ", "))
                                end
                                return fn(...)
                            end)
                            count = count + 1
                        end
                    end
                end)
                if not ok then wrapped[object] = nil end
            end
        end
        return count
    end

    local function unwrapNetworkTables()
        for object, keys in pairs(wrapped) do
            for key, fn in pairs(keys) do
                pcall(function() rawset(object, key, fn) end)
            end
        end
        wrapped = {}
    end

    local function watch(seconds)
        if watching then
            ctx.Notify("already watching", 3, "Crawl")
            return
        end

        watchLog = {}
        watching = true

        local hooked = startRemoteHook()
        local wrappedCount = wrapNetworkTables()
        watchLog[#watchLog + 1] = ("watch started: namecall hook=%s, wrapped fns=%d")
            :format(tostring(hooked), wrappedCount)

        ctx.Notify(("watching for %ds - play a round now"):format(seconds), 5, "Crawl")

        -- attribute + GUI text polling
        local lastAttrs, lastText = {}, {}

        local function pollAttributes(instance, label)
            local attrs = safe(function() return instance:GetAttributes() end, nil)
            if type(attrs) ~= "table" then return end
            for key, value in pairs(attrs) do
                local id = label .. "." .. tostring(key)
                local text = trim(value)
                if lastAttrs[id] ~= text then
                    if lastAttrs[id] ~= nil then
                        watchLog[#watchLog + 1] = ("%.2f  attribute %s: %s -> %s")
                            :format(os.clock(), id, lastAttrs[id], text)
                    end
                    lastAttrs[id] = text
                end
            end
        end

        local deadline = os.clock() + seconds
        while os.clock() < deadline and ctx.IsAlive() do
            pollAttributes(LocalPlayer, "LocalPlayer")
            local character = safe(function() return LocalPlayer.Character end, nil)
            if character then pollAttributes(character, "Character") end

            local gui = safe(function() return LocalPlayer:FindFirstChild("PlayerGui") end, nil)
            if gui then
                local descendants = safe(function() return gui:GetDescendants() end, nil)
                if type(descendants) == "table" then
                    for _, item in ipairs(descendants) do
                        local class = safe(function() return item.ClassName end, "")
                        if class == "TextLabel" or class == "TextButton" or class == "TextBox" then
                            local path = safe(function() return item:GetFullName() end, "?")
                            local text = trim(safe(function() return item.Text end, ""))
                            if lastText[path] ~= text then
                                if lastText[path] ~= nil then
                                    watchLog[#watchLog + 1] = ("%.2f  text %s: %q -> %q")
                                        :format(os.clock(), path, lastText[path], text)
                                end
                                lastText[path] = text
                            end
                        end
                    end
                end
            end

            task.wait(0.1)
        end

        watching = false
        unwrapNetworkTables()
        if restoreHook then
            restoreHook()
            restoreHook = nil
        end

        ctx.Notify(("watch finished - %d events"):format(#watchLog), 5, "Crawl")
    end

    ----------------------------------------------------------------- output
    local function fullText()
        local parts = { table.concat(report, "\n") }
        if #watchLog > 0 then
            parts[#parts + 1] = "\n\n==== watch log (" .. #watchLog .. " events) ====\n"
                .. table.concat(watchLog, "\n")
        end
        return table.concat(parts, "")
    end

    local function save()
        local text = fullText()
        if #text == 0 then
            ctx.Notify("nothing to save - run Crawl game first", 4, "Crawl")
            return
        end

        local path = ("namdevHub/crawl-%d-%d.txt"):format(ctx.GameInfo.PlaceId, os.time())
        if writefile then
            local ok = pcall(function()
                if makefolder and not (isfolder and isfolder("namdevHub")) then
                    pcall(makefolder, "namdevHub")
                end
                writefile(path, text)
            end)
            if ok then
                ctx.Notify(("saved %d KB to %s"):format(math.floor(#text / 1024), path), 8, "Crawl")
                return path
            end
        end
        ctx.Notify("this executor has no writefile - use Copy to clipboard", 6, "Crawl")
        return nil
    end

    -------------------------------------------------------------------- UI
    ctx.Tab:AddParagraph({
        Title   = "Crawl",
        Content = "Dumps what this game actually looks like so a script can be written "
               .. "against it. Run 'Crawl game', then 'Watch a round' and play one turn, "
               .. "then 'Save report' and send the file.",
    })

    ctx.Tab:AddSlider("Crawl_MaxNodes", {
        Title = "Max instances per service", Default = 8000, Min = 500, Max = 40000, Rounding = 0,
    }):OnChanged(function(value) settings.maxNodes = value end)

    ctx.Tab:AddSlider("Crawl_MaxDepth", {
        Title = "Max tree depth", Default = 8, Min = 2, Max = 20, Rounding = 0,
    }):OnChanged(function(value) settings.maxDepth = value end)

    ctx.Tab:AddSlider("Crawl_WatchFor", {
        Title = "Watch duration (seconds)", Default = 30, Min = 5, Max = 180, Rounding = 0,
    }):OnChanged(function(value) settings.watchFor = value end)

    local summary

    ctx.Tab:AddButton({
        Title       = "Crawl game",
        Description = "Snapshot instances, remotes, attributes and memory",
        Callback    = function()
            ctx.Spawn(function()
                ctx.Notify("crawling...", 3, "Crawl")
                local ok, text = pcall(crawl)
                if not ok then
                    ctx.Notify("crawl failed: " .. tostring(text), 8, "Crawl")
                    return
                end
                ctx.Notify(("crawl done - %d lines, %d KB"):format(#report,
                    math.floor(#text / 1024)), 6, "Crawl")
                if summary then
                    pcall(function()
                        summary:SetDesc(("%d lines, %d remotes, %d KB - Save report next")
                            :format(#report, #remotes, math.floor(#text / 1024)))
                    end)
                end
            end)
        end,
    })

    -- Targeted check of everything the Finish The Word module depends on, so a
    -- failure points at one line instead of "it doesn't work".
    ctx.Tab:AddButton({
        Title       = "Probe Finish The Word",
        Description = "Checks each thing the FTW module needs and reports which is missing",
        Callback    = function()
            ctx.Spawn(function()
                report = {}
                out("==== Finish The Word probe ====")
                out("PlaceId: %d   GameId: %d", ctx.GameInfo.PlaceId, ctx.GameInfo.GameId)
                out("getgc: %s   getloadedmodules: %s   hookmetamethod: %s",
                    tostring(getgc ~= nil), tostring(getloadedmodules ~= nil),
                    tostring(hookmetamethod ~= nil))

                local attrs = safe(function() return LocalPlayer:GetAttributes() end, nil)
                out("")
                out("LocalPlayer attributes:")
                if type(attrs) == "table" and next(attrs) then
                    for key, value in pairs(attrs) do
                        out("  %s = %s", tostring(key), trim(value))
                    end
                else
                    out("  (none - so IsTurn is NOT an attribute on the player here)")
                end

                if not getgc then
                    out("")
                    out("no getgc: this executor cannot find the game's tables at all")
                else
                    local objects = safe(function() return getgc(true) end, {})
                    out("")
                    out("gc objects: %d", #objects)

                    local net, question, wordString = nil, nil, nil
                    local fireLike, questionLike = {}, {}

                    for _, object in ipairs(objects) do
                        if type(object) == "table" then
                            pcall(function()
                                if rawget(object, "remoteFire") and rawget(object, "remoteConnect")
                                    and rawget(object, "fire") and rawget(object, "ping") then
                                    net = object
                                elseif rawget(object, "fire") or rawget(object, "remoteFire") then
                                    if #fireLike < 10 then fireLike[#fireLike + 1] = object end
                                end

                                if rawget(object, "QuestionLabel")
                                    and (rawget(object, "RequiredLetter") or rawget(object, "Choices")) then
                                    question = object
                                elseif rawget(object, "RequiredLetter") or rawget(object, "QuestionLabel")
                                    or rawget(object, "Choices") then
                                    if #questionLike < 10 then questionLike[#questionLike + 1] = object end
                                end
                            end)
                        elseif type(object) == "string" and not wordString
                            and object:find("whitelistedFtwWords", 1, true) then
                            wordString = object
                        end
                    end

                    local function dumpKeys(label, object)
                        local keys = {}
                        pcall(function()
                            for key, value in pairs(object) do
                                if #keys < 40 then
                                    keys[#keys + 1] = tostring(key) ..
                                        (type(value) == "function" and "()" or "")
                                end
                            end
                        end)
                        table.sort(keys)
                        out("  %s: %s", label, table.concat(keys, ", "))
                    end

                    out("")
                    out("network table (needs remoteFire+remoteConnect+fire+ping): %s",
                        net and "FOUND" or "NOT FOUND")
                    if net then dumpKeys("keys", net) end
                    if #fireLike > 0 then
                        out("  near-misses with a fire/remoteFire key: %d", #fireLike)
                        for i, object in ipairs(fireLike) do dumpKeys("candidate " .. i, object) end
                    end

                    out("")
                    out("question table (needs QuestionLabel + RequiredLetter/Choices): %s",
                        question and "FOUND" or "NOT FOUND")
                    if question then dumpKeys("keys", question) end
                    if #questionLike > 0 then
                        out("  near-misses: %d", #questionLike)
                        for i, object in ipairs(questionLike) do dumpKeys("candidate " .. i, object) end
                    end

                    out("")
                    out("word list string containing 'whitelistedFtwWords': %s",
                        wordString and ("FOUND, " .. #wordString .. " bytes") or "NOT FOUND")
                end

                local text = table.concat(report, "\n")
                ctx.Notify("probe done - Save report or Copy to clipboard", 6, "Crawl")
                if summary then
                    pcall(function() summary:SetDesc(("probe: %d lines"):format(#report)) end)
                end
                return text
            end)
        end,
    })

    -- The match UI only exists while a round is running, so it misses the
    -- full crawl done in the lobby. This grabs just that, on demand.
    ctx.Tab:AddButton({
        Title       = "Dump match UI now",
        Description = "PlayerGui + your table, mid-round - run this while playing",
        Callback    = function()
            ctx.Spawn(function()
                report = {}
                out("==== match UI dump ====")
                out("clock: %s   IsTurn: %s", tostring(os.time()),
                    tostring(safe(function() return LocalPlayer:GetAttribute("IsTurn") end, nil)))

                local gui = safe(function() return LocalPlayer:FindFirstChild("PlayerGui") end, nil)
                if gui then
                    out("")
                    out("---- PlayerGui ----")
                    walk(gui, 0, { count = 0 })
                end

                -- the table you are sitting at
                local character = safe(function() return LocalPlayer.Character end, nil)
                local humanoid = character and safe(function()
                    return character:FindFirstChildOfClass("Humanoid")
                end, nil)
                local seat = humanoid and safe(function() return humanoid.SeatPart end, nil)

                out("")
                out("---- your seat ----")
                out("SeatPart: %s", seat and safe(function() return seat:GetFullName() end, "?") or "not seated")

                if seat then
                    local node = seat
                    while node and node ~= workspace do
                        local display = safe(function() return node:FindFirstChild("Table") end, nil)
                        if display then
                            out("")
                            out("---- your table ----")
                            walk(node, 0, { count = 0 })
                            break
                        end
                        node = safe(function() return node.Parent end, nil)
                    end
                end

                ctx.Notify("match UI dumped - Save report or Copy to clipboard", 6, "Crawl")
                if summary then
                    pcall(function() summary:SetDesc(("match dump: %d lines"):format(#report)) end)
                end
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Watch a round",
        Description = "Record remotes, attributes and GUI text while you play",
        Callback    = function()
            ctx.Spawn(function() watch(settings.watchFor) end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Save report",
        Description = "Writes crawl + watch log to a file",
        Callback    = function() ctx.Spawn(save) end,
    })

    ctx.Tab:AddButton({
        Title       = "Copy report to clipboard",
        Description = "For executors without writefile (may be truncated)",
        Callback    = function()
            local text = fullText()
            if #text == 0 then
                ctx.Notify("nothing to copy - run Crawl game first", 4, "Crawl")
            elseif setclipboard then
                setclipboard(text)
                ctx.Notify(("copied %d KB"):format(math.floor(#text / 1024)), 5, "Crawl")
            else
                ctx.Notify("no setclipboard in this executor", 5, "Crawl")
            end
        end,
    })

    summary = ctx.Tab:AddParagraph({ Title = "Last crawl", Content = "-" })

    ctx.OnUnload(function()
        watching = false
        unwrapNetworkTables()
        if restoreHook then
            restoreHook()
            restoreHook = nil
        end
    end)
end

return M
]=]
__sources["src/scripts/finish_the_word"] = [=[
--[[
    Finish The Word! - word solver / auto answer
    ============================================
    Rewritten against a real crawl of the live game (PlaceId 91704854174760),
    not against the assumptions in the obfuscated script that was handed over.

    What the crawl showed, and what this module therefore does:

      * Your turn is `LocalPlayer:GetAttribute("IsTurn")` (this part the old
        script had right - it flips true/false per turn).
      * The prompt is NOT a Lua table in memory. It is UI. The table you are
        sitting at carries a BillboardGui "MatchDisplay" whose "Category"
        TextLabel holds the prompt: a letter fragment like "CE", "IT", "ME",
        or a category word like "Animals", or "Choose a letter" during the
        letter-pick phase.
      * Your seat identifies your table: Humanoid.SeatPart -> ... -> Table.
      * Letters you type appear as MatchDisplay.AnswerInput.Keys.<n>, and the
        HUD mirrors them in PlayerGui.ScreenGui.TopBar.AnswerInput.Keys.<n>.
      * Answering is keyboard input - the game reads real keystrokes - so the
        answer is typed with VirtualInputManager and submitted with Return.
        (The original script grabbed VirtualInputManager and VirtualUser for
        exactly this reason.)
      * getgc on this game/executor exposes nothing useful: no game tables, no
        word list. So the dictionary is downloaded instead.

    The prompt is treated as a SUBSTRING the word must contain, which is what
    "Finish The Word" fragments like "CE" / "IT" / "ME" imply. Switch the
    Match mode dropdown to "Starts with" if a round behaves otherwise.
]]

local M = {}

function M.Setup(ctx)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    ------------------------------------------------------------------ state
    local settings = {
        autoAnswer   = false,
        matchMode    = "Contains",
        pickShortest = true,
        typeDelay    = 0.06,
        answerDelay  = 0.5,
        suggestCount = 15,
    }

    local words, known, rank = {}, {}, {}
    local used = {}
    local wordCount = 0
    local answeredPrompt = nil
    local answering = false

    local statusBox, suggestionBox

    ------------------------------------------------------------- dictionary
    local WORD_SOURCES = {
        { name = "common 10k", ranked = true,
          url = "https://raw.githubusercontent.com/first20hours/google-10000-english/master/google-10000-english-usa.txt" },
        { name = "popular 25k",
          url = "https://raw.githubusercontent.com/dolph/dictionary/master/popular.txt" },
    }
    local FULL_DICTIONARY = { name = "full dictionary",
        url = "https://raw.githubusercontent.com/dwyl/english-words/master/words_alpha.txt" }

    local function addWord(word)
        if known[word] then return end
        known[word] = true
        words[#words + 1] = word
        wordCount = wordCount + 1
    end

    local function ingest(text, ranked)
        local added, index = 0, 0
        for line in tostring(text):gmatch("[^\r\n]+") do
            index = index + 1
            local word = line:lower():match("^%s*(%a+)%s*$")
            if word then
                if ranked and rank[word] == nil then rank[word] = index end
                if not known[word] then
                    addWord(word)
                    added = added + 1
                end
            end
        end
        return added
    end

    local function httpGet(url)
        local requester = (syn and syn.request) or http_request or request
        if requester then
            local ok, response = pcall(requester, { Url = url, Method = "GET" })
            if ok and type(response) == "table" and response.Body
                and (response.StatusCode == 200 or response.StatusCode == nil) then
                return response.Body
            end
        end
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and #body > 0 then return body end
        return nil
    end

    local function downloadDictionary(includeFull)
        local added = 0
        for _, source in ipairs(WORD_SOURCES) do
            local body = httpGet(source.url)
            if body then
                added = added + ingest(body, source.ranked)
            else
                ctx.Notify("could not download " .. source.name, 5, "Finish The Word")
            end
        end
        if includeFull then
            local body = httpGet(FULL_DICTIONARY.url)
            if body then added = added + ingest(body) end
        end
        return added
    end

    ------------------------------------------------------------ game lookup
    -- Your seat tells us which table you are playing at.
    local function currentTable()
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local seat = humanoid and humanoid.SeatPart
        if not seat then return nil end

        local node = seat
        while node and node ~= workspace do
            local display = node:FindFirstChild("Table")
            if display and display:FindFirstChild("MatchDisplay") then
                return display
            end
            node = node.Parent
        end
        return nil
    end

    -- The prompt text, from the table you are at, falling back to any active
    -- MatchDisplay if the seat lookup fails.
    local function promptLabel()
        local tableModel = currentTable()
        if tableModel then
            local display = tableModel:FindFirstChild("MatchDisplay")
            local category = display and display:FindFirstChild("Category")
            if category then return category end
        end

        local meta = workspace:FindFirstChild("Meta")
        local tables = meta and meta:FindFirstChild("Tables")
        if not tables then return nil end
        for _, model in ipairs(tables:GetChildren()) do
            local display = model:FindFirstChild("Table")
            display = display and display:FindFirstChild("MatchDisplay")
            if display and display:GetAttribute("Active") == true then
                local category = display:FindFirstChild("Category")
                if category then return category end
            end
        end
        return nil
    end

    -- What has already been typed into the answer box, so we only type the rest.
    local function typedSoFar()
        local tableModel = currentTable()
        local display = tableModel and tableModel:FindFirstChild("MatchDisplay")
        local input = display and display:FindFirstChild("AnswerInput")
        local keys = input and input:FindFirstChild("Keys")
        if not keys then return "" end

        local letters = {}
        for _, key in ipairs(keys:GetChildren()) do
            local index = tonumber(key.Name)
            if index then
                local label = key:FindFirstChildWhichIsA("TextLabel", true)
                letters[index] = label and label.Text or ""
            end
        end

        local out = {}
        for i = 1, #letters do out[#out + 1] = letters[i] or "" end
        return table.concat(out):lower()
    end

    local function isMyTurn()
        local ok, value = pcall(function()
            return LocalPlayer:GetAttribute("IsTurn")
        end)
        return ok and value == true
    end

    ------------------------------------------------------------------ input
    -- The game reads real keystrokes, so we send real keystrokes.
    local virtualInput
    do
        local ok, service = pcall(function()
            return Instance.new("VirtualInputManager")
        end)
        if ok then virtualInput = service end
        if not virtualInput then
            ok, service = pcall(function()
                return game:GetService("VirtualInputManager")
            end)
            if ok then virtualInput = service end
        end
    end

    local function pressKey(keyCode)
        if not virtualInput then return false end
        local ok = pcall(function()
            virtualInput:SendKeyEvent(true, keyCode, false, game)
        end)
        task.wait(0.01)
        pcall(function()
            virtualInput:SendKeyEvent(false, keyCode, false, game)
        end)
        return ok
    end

    local function typeWord(word, alreadyTyped)
        local start = #alreadyTyped + 1
        if word:sub(1, #alreadyTyped) ~= alreadyTyped then
            start = 1   -- what is on screen is not our word; type the whole thing
        end

        for i = start, #word do
            if not ctx.IsAlive() or not isMyTurn() then return false end
            local letter = word:sub(i, i):upper()
            local keyCode = Enum.KeyCode[letter]
            if keyCode then pressKey(keyCode) end
            task.wait(settings.typeDelay)
        end

        task.wait(settings.answerDelay)
        if not ctx.IsAlive() or not isMyTurn() then return false end
        pressKey(Enum.KeyCode.Return)
        return true
    end

    ------------------------------------------------------------- word search
    local function matches(word, fragment)
        if settings.matchMode == "Starts with" then
            return word:sub(1, #fragment) == fragment
        end
        return word:find(fragment, 1, true) ~= nil
    end

    local function candidates(fragment, limit)
        local out = {}
        for _, word in ipairs(words) do
            if not used[word] and matches(word, fragment) then
                out[#out + 1] = word
                if limit and #out >= limit * 6 then break end
            end
        end

        table.sort(out, function(a, b)
            if settings.pickShortest then
                if #a ~= #b then return #a < #b end
            else
                local ra, rb = rank[a] or math.huge, rank[b] or math.huge
                if ra ~= rb then return ra < rb end
            end
            return a < b
        end)

        if limit and #out > limit then
            local trimmed = {}
            for i = 1, limit do trimmed[i] = out[i] end
            return trimmed
        end
        return out
    end

    ------------------------------------------------------------------- solve
    -- "CE" -> a fragment to solve. "Animals" / "Choose a letter" -> not one.
    local function fragmentFrom(text)
        if not text then return nil end
        local cleaned = text:match("^%s*(.-)%s*$"):lower()
        if #cleaned == 0 or #cleaned > 4 then return nil end
        if not cleaned:match("^%a+$") then return nil end
        return cleaned
    end

    local function solve(fragment)
        local list = candidates(fragment, 1)
        local word = list[1]
        if not word then
            ctx.Notify(('no word contains "%s"'):format(fragment), 4, "Finish The Word")
            return
        end

        used[word] = true
        if typeWord(word, typedSoFar()) then
            ctx.Notify("answered: " .. word, 3, "Finish The Word")
        end
    end

    ------------------------------------------------------------------- UI
    local function refresh(fragment)
        if not suggestionBox then return end
        local lines
        if not fragment then
            lines = { "-" }
        elseif wordCount == 0 then
            lines = { "no dictionary loaded" }
        else
            lines = candidates(fragment, settings.suggestCount)
            if #lines == 0 then lines = { ('no word contains "%s"'):format(fragment) } end
        end
        pcall(function() suggestionBox:SetDesc(table.concat(lines, "\n")) end)
    end

    local function updateStatus(label, fragment, turn)
        if not statusBox then return end
        pcall(function()
            statusBox:SetDesc(("words: %d   typing: %s   prompt: %s   IsTurn: %s")
                :format(wordCount,
                        virtualInput and "ready" or "NO VirtualInputManager",
                        fragment or (label and ('"%s" (not a letter prompt)'):format(label.Text)) or "none",
                        turn and "true" or "false"))
        end)
    end

    ctx.Tab:AddParagraph({
        Title   = "Finish The Word!",
        Content = "Reads the prompt off your table's Category label and types an answer with "
               .. "real keystrokes. Sit at a table and turn Auto answer on.",
    })

    ctx.Tab:AddToggle("FTW_AutoAnswer", { Title = "Auto answer", Default = false })
        :OnChanged(function(value) settings.autoAnswer = value end)

    ctx.Tab:AddDropdown("FTW_MatchMode", {
        Title = "Match mode", Values = { "Contains", "Starts with" }, Default = 1,
    }):OnChanged(function(value) settings.matchMode = tostring(value) end)

    ctx.Tab:AddToggle("FTW_Shortest", {
        Title = "Prefer shortest word",
        Description = "Off = prefer the most common word instead",
        Default = true,
    }):OnChanged(function(value) settings.pickShortest = value end)

    ctx.Tab:AddSlider("FTW_TypeDelay", {
        Title = "Typing delay", Default = 0.06, Min = 0.01, Max = 0.4, Rounding = 2,
    }):OnChanged(function(value) settings.typeDelay = value end)

    ctx.Tab:AddSlider("FTW_AnswerDelay", {
        Title = "Delay before submitting", Default = 0.5, Min = 0, Max = 3, Rounding = 1,
    }):OnChanged(function(value) settings.answerDelay = value end)

    ctx.Tab:AddSlider("FTW_SuggestCount", {
        Title = "Suggestion count", Default = 15, Min = 1, Max = 50, Rounding = 0,
    }):OnChanged(function(value) settings.suggestCount = value end)

    ctx.Tab:AddButton({
        Title       = "Answer now",
        Description = "Solve the current prompt once, ignoring Auto answer",
        Callback    = function()
            ctx.Spawn(function()
                local label = promptLabel()
                local fragment = fragmentFrom(label and label.Text)
                if not fragment then
                    ctx.Notify("no letter prompt on your table right now", 4, "Finish The Word")
                    return
                end
                solve(fragment)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Download full dictionary",
        Description = "~370k words - better coverage, slower",
        Callback    = function()
            ctx.Spawn(function()
                ctx.Notify("downloading...", 4, "Finish The Word")
                local added = downloadDictionary(true)
                ctx.Notify(("+%d words (%d total)"):format(added, wordCount), 5, "Finish The Word")
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Clear used words",
        Description = "Words already answered this session become available again",
        Callback    = function()
            used = {}
            ctx.Notify("used list cleared", 3, "Finish The Word")
        end,
    })

    statusBox = ctx.Tab:AddParagraph({ Title = "Status", Content = "-" })
    suggestionBox = ctx.Tab:AddParagraph({ Title = "Suggestions", Content = "-" })

    -- Read the controls off the UI every tick. OnChanged alone misses values
    -- restored from a saved config or set with SetValue, which is why "Auto
    -- answer" could look enabled while nothing happened.
    local OPTION_MAP = {
        FTW_AutoAnswer  = "autoAnswer",
        FTW_MatchMode   = "matchMode",
        FTW_Shortest    = "pickShortest",
        FTW_TypeDelay   = "typeDelay",
        FTW_AnswerDelay = "answerDelay",
        FTW_SuggestCount = "suggestCount",
    }

    local function syncOptions()
        local options = ctx.Options
        if not options then return end
        for id, key in pairs(OPTION_MAP) do
            local option = options[id]
            if option ~= nil then
                local ok, value = pcall(function() return option.Value end)
                if ok and value ~= nil then
                    settings[key] = (key == "matchMode") and tostring(value) or value
                end
            end
        end
    end

    ------------------------------------------------------------------- run
    if not virtualInput then
        ctx.Tab:AddParagraph({
            Title   = "Typing unavailable",
            Content = "This executor would not give a VirtualInputManager, so keystrokes "
                   .. "cannot be sent. Suggestions still work - type them yourself.",
        })
    end

    ctx.Spawn(function()
        ctx.Notify("loading dictionary...", 4, "Finish The Word")
        local added = downloadDictionary(false)
        ctx.Notify(added > 0 and ("loaded %d words"):format(added)
            or "could not load a dictionary - check HTTP support", 5, "Finish The Word")
    end)

    ctx.Spawn(function()
        while ctx.IsAlive() do
            syncOptions()
            local turn = isMyTurn()
            local label = promptLabel()
            local fragment = fragmentFrom(label and label.Text)

            refresh(fragment)
            updateStatus(label, fragment, turn)

            if fragment and turn and settings.autoAnswer and not answering
                and fragment ~= answeredPrompt and wordCount > 0 then
                answeredPrompt = fragment
                answering = true
                local ok, err = pcall(solve, fragment)
                answering = false
                if not ok then ctx.Notify("error: " .. tostring(err), 6, "Finish The Word") end
            end

            if not turn then answeredPrompt = nil end
            task.wait(0.2)
        end
    end)
end

return M
]=]
__sources["src/scripts/spelling_race"] = [=[
--[[
    Spelling Race - auto spell
    ==========================
    Deobfuscated from "auto spell keyless.txt" (WeAreDevs obfuscator v1.0.0,
    original by light2light) and adapted to the hub module contract.

    How the game hides the answer, innermost first:
      1. the word is turned into ASCII codes
      2. each code has its DIGITS REVERSED          ("a" = 97 -> "79")
      3. codes are joined with commas
      4. every byte is XOR'd with a repeating key:  "1144" .. PlaceId .. "00552002"
      5. the result lives in the "Color" attribute of the Texture under a
         scenery part in workspace.Floors2
      6. Lighting.Bloom.Sky.StarCount is a per-round offset subtracted from
         every character code

    If the payload is missing or unusable the script falls back to the first
    non-empty AnswerControl.Answer1..4 value, exactly like the original.
]]

local M = {}

local HIDDEN_PART = "Part +R2107+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R22+2"

function M.Setup(ctx)
    local ReplicatedStorage = game:GetService("ReplicatedStorage")

    local RoundControl = ReplicatedStorage:WaitForChild("RoundControlFolder", 10)
    local Remotes      = ReplicatedStorage:WaitForChild("Remotes", 10)
    if not (RoundControl and Remotes) then
        ctx.Tab:AddParagraph({
            Title   = "Not in a round yet",
            Content = "RoundControlFolder / Remotes were not found. Rejoin once a match is running and re-execute.",
        })
        return
    end

    local TopicControl  = RoundControl:WaitForChild("TopicControl", 10)
    local AnswerControl = RoundControl:WaitForChild("AnswerControl", 10)
    local SubmitAnswer  = Remotes:WaitForChild("SubmitAnswerRemote", 10)
    local TopicDesc     = TopicControl and TopicControl:WaitForChild("TopicDesc", 10)

    if not (TopicDesc and AnswerControl and SubmitAnswer) then
        ctx.Tab:AddParagraph({
            Title   = "Game layout changed",
            Content = "TopicDesc / AnswerControl / SubmitAnswerRemote missing - the script needs updating.",
        })
        return
    end

    --------------------------------------------------------------- settings
    local settings = {
        autoSpell   = true,
        answerDelay = 2.2,
        randomize   = true,
        notify      = true,
    }

    local function say(text, duration)
        if settings.notify then
            ctx.Notify(text, duration or 3, "Spelling Race")
        end
    end

    --------------------------------------------------------------- decoding
    local function readPayload()
        local floors = workspace:FindFirstChild("Floors2")
        if not floors then return nil end

        local part = floors:FindFirstChild(HIDDEN_PART)
        if not part then return nil end

        local texture = part:FindFirstChildOfClass("Texture")
        if not texture then return nil end

        return texture:GetAttribute("Color")
    end

    local function decodeWord()
        local payload = readPayload()
        if not payload or payload == "" then return nil end

        -- undo the XOR; bytes that come out as letters are corrupt and
        -- collapse into the "," separator so they drop out of the split
        local key   = "1144" .. game.PlaceId .. "00552002"
        local plain = {}
        for i = 1, #payload do
            local b = bit32.bxor(payload:byte(i), key:byte((i - 1) % #key + 1))
            if (b >= 65 and b <= 90) or (b >= 97 and b <= 122) then
                b = 44
            end
            plain[i] = string.char(b)
        end

        local offset = 0
        pcall(function()
            offset = game.Lighting.Bloom.Sky.StarCount
        end)

        local word = ""
        for _, chunk in ipairs(string.split(table.concat(plain), ",")) do
            local code = tonumber(string.reverse(chunk))
            if code then
                code = code - offset
                if code >= 32 and code <= 126 then
                    word = word .. string.char(code)
                end
            end
        end

        if word ~= "" then return word end
        return nil
    end

    local function fallbackAnswer()
        for i = 1, 4 do
            local answer = AnswerControl:FindFirstChild("Answer" .. i)
            local value  = answer and answer.Value or ""
            if value ~= "" then return value end
        end
        return ""
    end

    --------------------------------------------------------------- submitting
    local function submit(word, elapsed)
        -- the trailing two spaces are part of what the original sends
        local ok, result = pcall(function()
            return SubmitAnswer:InvokeServer(word .. "  ", "keyboard", nil, elapsed)
        end)
        if not ok then
            say("Submit failed: " .. tostring(result), 6)
            return nil
        end

        if result then
            if result.correct then
                say("Correct! +" .. tostring(result.score))
            elseif result.closeAnswer then
                say("Close! +" .. tostring(result.score))
            else
                say("Wrong: " .. tostring(result.correctAnswer or "?"))
            end
        end
        return result
    end

    local function currentWord()
        local word
        for _ = 1, 5 do
            if not ctx.IsAlive() then return nil end
            word = decodeWord()
            if word then return word end
            task.wait(0.5)
        end
        return nil
    end

    local busy = false

    local function solveRound()
        if busy or not ctx.IsAlive() or not settings.autoSpell then return end
        busy = true

        say("Loading word...")
        task.wait(1)

        local word = currentWord() or fallbackAnswer()
        if word == "" or not ctx.IsAlive() then
            busy = false
            return
        end

        say("Word: " .. word)

        local delay = settings.answerDelay
        if settings.randomize then
            delay = delay + (math.random() - 0.5) -- +/- 0.5s jitter
        end
        task.wait(delay)

        if ctx.IsAlive() and settings.autoSpell then
            say("Spelling...")
            submit(word, delay - 0.7)
        end
        busy = false
    end

    --------------------------------------------------------------- interface
    ctx.Tab:AddParagraph({
        Title   = "Spelling Race",
        Content = "Reads the round's word straight out of the game and answers it. "
               .. "Answer Time 2.2 with Randomize on looks the most human.",
    })

    local autoToggle = ctx.Tab:AddToggle("SpellingRace_AutoSpell", {
        Title   = "Auto Spell",
        Default = true,
    })
    autoToggle:OnChanged(function(value)
        settings.autoSpell = value
    end)

    ctx.Tab:AddSlider("SpellingRace_AnswerDelay", {
        Title       = "Answer Time",
        Description = "Delay before answering (seconds)",
        Default     = 2.2,
        Min         = 0.1,
        Max         = 5,
        Rounding    = 1,
        Callback    = function(value)
            settings.answerDelay = value
        end,
    })

    local randomToggle = ctx.Tab:AddToggle("SpellingRace_Randomize", {
        Title       = "Randomize Time",
        Description = "Adds up to +/- 0.5s of jitter",
        Default     = true,
    })
    randomToggle:OnChanged(function(value)
        settings.randomize = value
    end)

    local notifyToggle = ctx.Tab:AddToggle("SpellingRace_Notifications", {
        Title   = "Notifications",
        Default = true,
    })
    notifyToggle:OnChanged(function(value)
        settings.notify = value
    end)

    ctx.Tab:AddButton({
        Title       = "Spell Now",
        Description = "Answer the current word immediately",
        Callback    = function()
            ctx.Spawn(function()
                local word = decodeWord() or fallbackAnswer()
                if word == "" then
                    ctx.Notify("No word available yet", 4, "Spelling Race")
                    return
                end
                ctx.Notify("Spelling now...", 3, "Spelling Race")
                submit(word, 0.1)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Show decoded word",
        Description = "Peek at the answer without submitting",
        Callback    = function()
            local word = decodeWord()
            ctx.Notify(word and ("Word: " .. word) or "Payload not readable right now", 5, "Spelling Race")
        end,
    })

    --------------------------------------------------------------- run
    ctx.Connect(TopicDesc:GetPropertyChangedSignal("Value"), function()
        if TopicDesc.Value ~= "" then
            ctx.Spawn(solveRound)
        end
    end)

    if TopicDesc.Value ~= "" then
        ctx.Spawn(solveRound)
    end
end

return M
]=]
__sources["src/scripts/universal"] = [=[
--[[
    Universal tools
    ===============
    Loaded in every game (Universal = true in the registry). Keep this file
    for things that never depend on a specific place: server hopping, rejoin,
    FPS/ping readouts, character conveniences.

    It also doubles as the reference implementation of the module contract:
      Setup(ctx) with ctx.Tab / ctx.Notify / ctx.Connect / ctx.Spawn /
      ctx.OnUnload / ctx.IsAlive.
]]

local M = {}

function M.Setup(ctx)
    local Players         = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")
    local HttpService     = game:GetService("HttpService")
    local RunService      = game:GetService("RunService")
    local StarterGui      = game:GetService("StarterGui")

    local LocalPlayer = Players.LocalPlayer

    ctx.Tab:AddParagraph({
        Title   = "Server",
        Content = "Works in any game.",
    })

    ctx.Tab:AddButton({
        Title       = "Rejoin",
        Description = "Teleport back into this place",
        Callback    = function()
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Server hop",
        Description = "Jump to another public server of this game",
        Callback    = function()
            ctx.Spawn(function()
                local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100")
                    :format(game.PlaceId)

                local ok, body = pcall(function()
                    return game:HttpGet(url)
                end)
                if not ok then
                    ctx.Notify("Server list request failed", 5)
                    return
                end

                local decoded
                ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
                if not ok or type(decoded) ~= "table" or not decoded.data then
                    ctx.Notify("Could not read the server list", 5)
                    return
                end

                for _, server in ipairs(decoded.data) do
                    if server.playing and server.maxPlayers
                        and server.playing < server.maxPlayers
                        and server.id ~= game.JobId then
                        ctx.Notify("Hopping...", 4)
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
                        return
                    end
                end

                ctx.Notify("No other server with room", 5)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Copy JobId",
        Description = "This server's instance id",
        Callback    = function()
            if setclipboard then
                setclipboard(game.JobId)
                ctx.Notify("JobId copied")
            else
                ctx.Notify("No setclipboard in this executor", 5)
            end
        end,
    })

    ------------------------------------------------------------------ player
    ctx.Tab:AddParagraph({ Title = "Character", Content = "" })

    ctx.Tab:AddSlider("Universal_WalkSpeed", {
        Title    = "WalkSpeed",
        Default  = 16,
        Min      = 16,
        Max      = 200,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = value end
        end,
    })

    ctx.Tab:AddSlider("Universal_JumpPower", {
        Title    = "JumpPower",
        Default  = 50,
        Min      = 50,
        Max      = 300,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.UseJumpPower = true
                hum.JumpPower    = value
            end
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Reset character",
        Description = "Breaks joints on your humanoid",
        Callback    = function()
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.Health = 0 end
        end,
    })

    ------------------------------------------------------------------ stats
    local statsParagraph = ctx.Tab:AddParagraph({
        Title   = "Stats",
        Content = "FPS: -   Ping: -",
    })

    ctx.Spawn(function()
        while ctx.IsAlive() do
            local fps, ping = "-", "-"
            pcall(function()
                local dt = RunService.RenderStepped:Wait()
                if type(dt) == "number" and dt > 0 then
                    fps = tostring(math.floor(1 / dt))
                end
            end)
            pcall(function()
                ping = math.floor(LocalPlayer:GetNetworkPing() * 1000) .. "ms"
            end)
            pcall(function()
                statsParagraph:SetDesc(("FPS: %s   Ping: %s"):format(fps, ping))
            end)
            task.wait(1)
        end
    end)
end

return M
]=]

local __cache = {}
local function __require(path)
    if __cache[path] ~= nil then return __cache[path] end
    local source = __sources[path]
    if not source then error('[Hub] unknown module: ' .. tostring(path), 0) end
    local chunk, err = loadstring(source, '@' .. path)
    if not chunk then error('[Hub] syntax error in ' .. path .. ': ' .. tostring(err), 0) end
    __cache[path] = chunk()
    return __cache[path]
end
genv.HUB_REQUIRE = __require
HUB_REQUIRE = __require

local CONFIG = {
    Name = "namdevHub",
    Version = "1.0.0",
    BaseUrl = "",
    CacheBust = false,
    Debug = false,
}

return __require('src/core').Start(CONFIG)
